import unreal

# Check if the UEBridge subsystem's file polling could be causing stalls
# Also check for any heavy ticking actors

sub = unreal.get_editor_subsystem(unreal.EditorActorSubsystem)
actors = sub.get_all_level_actors()

# Check for actors with ticking enabled
tick_actors = []
for a in actors:
    try:
        if a.primary_actor_tick.get_editor_property('b_start_with_tick_enabled'):
            tick_actors.append(a.get_actor_label())
    except:
        pass

print(f"Actors with tick enabled: {len(tick_actors)}")
if tick_actors:
    for t in tick_actors[:20]:
        print(f"  - {t}")

# Check SceneCapture2D - these are expensive
scene_captures = [a for a in actors if 'SceneCapture' in type(a).__name__]
for sc in scene_captures:
    label = sc.get_actor_label()
    hidden = sc.is_hidden_ed()
    print(f"\nSceneCapture2D: '{label}' hidden={hidden}")
    # Check if it's auto-capturing every frame
    comps = sc.get_components_by_class(unreal.SceneCaptureComponent2D)
    for c in comps:
        try:
            cap_source = c.get_editor_property('capture_source')
            cap_every = c.get_editor_property('capture_every_frame')
            print(f"  capture_every_frame={cap_every}, source={cap_source}")
        except Exception as e:
            print(f"  Could not read: {e}")

